	@Test
	void everyNonnegativePackedWidthRoundTrips(@TempDir Path directory) throws Exception {
		for (int width = 1; width <= 63; width++) {
			long maximum = width == 63 ? Long.MAX_VALUE : (1L << width) - 1L;
			long[] values = { 0L, maximum >>> 1, maximum };
			Path path = directory.resolve("width-" + width + ".fs2");
			try (FrontierStatisticsShardWriter writer = new FrontierStatisticsShardWriter(
					path, 41L, width, 52L, maximum, values.length)) {
				writer.addTermColumn(10, values);
				writer.finish();
			}
			try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(path)) {
				assertEquals(width, shard.column(10).bitWidth());
				for (int row = 0; row < values.length; row++) {
					assertEquals(values[row], shard.column(10).value(row), "width=" + width + ", row=" + row);
				}
			}
		}
	}

	private static void writeShard(Path path, long[] terms, long[] postings) throws IOException {
		try (FrontierStatisticsShardWriter writer = new FrontierStatisticsShardWriter(
				path, 7L, 3, 11L, 20_000_000_000L, terms.length)) {
			writer.addTermColumn(10, terms);
			writer.addDeltaColumn(20, postings);
			writer.finish();
		}
	}

	private static void repointSecondColumnAtFirstDataBlock(Path path) throws IOException {
		byte[] bytes = Files.readAllBytes(path);
		ByteBuffer file = ByteBuffer.wrap(bytes);
		int directoryOffset = Math.toIntExact(file.getLong(64));
		int firstEntry = directoryOffset;
		int secondEntry = directoryOffset + FrontierStatisticsShard.DIRECTORY_ENTRY_BYTES;
		int firstBlockDirectory = Math.toIntExact(file.getLong(firstEntry + 24));
		int secondBlockDirectory = Math.toIntExact(file.getLong(secondEntry + 24));
		int secondBlockDirectoryLength = Math.toIntExact(file.getLong(secondEntry + 32));
		long firstDataOffset = file.getLong(firstBlockDirectory + 16);
		file.putLong(secondBlockDirectory + 16, firstDataOffset);
		file.putInt(secondEntry + 56,
				FrontierStatisticsShard.checksum(slice(bytes, secondBlockDirectory, secondBlockDirectoryLength)));
		int directoryLength = Math.toIntExact(file.getLong(72));
		file.putInt(88, FrontierStatisticsShard.checksum(slice(bytes, directoryOffset, directoryLength)));
		file.putInt(FrontierStatisticsShard.HEADER_CHECKSUM_OFFSET, 0);
		file.putInt(FrontierStatisticsShard.HEADER_CHECKSUM_OFFSET,
				FrontierStatisticsShard.checksum(slice(bytes, 0, FrontierStatisticsShard.HEADER_BYTES)));
		Files.write(path, bytes);
	}

	private static void writeLegacyTermShard(Path path, long[] values, long maximumTermId) throws IOException {
		int bitWidth = FrontierStatisticsShard.bitWidth(maximumTermId);
		byte[] data = pack(values, bitWidth);
		long dataOffset = FrontierStatisticsShard.HEADER_BYTES;
		long directoryOffset = dataOffset + data.length;
		ByteBuffer directory = ByteBuffer.allocate(FrontierStatisticsShard.DIRECTORY_ENTRY_BYTES);
		directory.putInt(10);
		directory.putInt(FrontierStatisticsShard.CODEC_TERM_BITS);
		directory.putInt(bitWidth);
		directory.putInt(0);
		directory.putLong(values.length);
		directory.putLong(dataOffset);
		directory.putLong(data.length);
		directory.putLong(0L);
		directory.putLong(0L);
		directory.putInt(FrontierStatisticsShard.checksum(data));
		directory.putInt(0);
		byte[] directoryBytes = directory.array();
		long fileLength = directoryOffset + directoryBytes.length;
		byte[] bytes = new byte[Math.toIntExact(fileLength)];
		System.arraycopy(data, 0, bytes, Math.toIntExact(dataOffset), data.length);
		System.arraycopy(directoryBytes, 0, bytes, Math.toIntExact(directoryOffset), directoryBytes.length);
		ByteBuffer header = ByteBuffer.wrap(bytes);
		header.putLong(0, FrontierStatisticsShard.MAGIC);
		header.putInt(8, FrontierStatisticsShard.LEGACY_VERSION);
		header.putInt(12, FrontierStatisticsShard.HEADER_BYTES);
		header.putLong(16, 31L);
		header.putInt(24, 10);
		header.putLong(32, 42L);
		header.putLong(40, maximumTermId);
		header.putLong(48, values.length);
		header.putInt(56, 1);
		header.putLong(64, directoryOffset);
		header.putLong(72, directoryBytes.length);
		header.putLong(80, fileLength);
		header.putInt(88, FrontierStatisticsShard.checksum(directoryBytes));
		header.putInt(FrontierStatisticsShard.HEADER_CHECKSUM_OFFSET, 0);
		header.putInt(FrontierStatisticsShard.HEADER_CHECKSUM_OFFSET,
				FrontierStatisticsShard.checksum(slice(bytes, 0, FrontierStatisticsShard.HEADER_BYTES)));
		Files.write(path, bytes);
	}

	private static byte[] pack(long[] values, int bitWidth) throws IOException {
		byte[] packed = new byte[Math.toIntExact(FrontierStatisticsShard.encodedBytes(values.length, bitWidth))];
		long bitPosition = 0L;
		for (long value : values) {
			int remaining = bitWidth;
			int inputShift = 0;
			while (remaining > 0) {
				int byteIndex = Math.toIntExact(bitPosition >>> 3);
				int bitOffset = (int) (bitPosition & 7L);
				int copied = Math.min(remaining, Byte.SIZE - bitOffset);
				int mask = (1 << copied) - 1;
				packed[byteIndex] |= (byte) (((int) (value >>> inputShift) & mask) << bitOffset);
				bitPosition += copied;
				inputShift += copied;
				remaining -= copied;
			}
		}
		return packed;
	}

	private static ByteBuffer slice(byte[] bytes, int offset, int length) {
		return ByteBuffer.wrap(bytes, offset, length).slice();
	}
